import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"日志采集与查询：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"日志采集与查询：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"observability","title":"日志采集与查询","link":"/topics/observability/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"日志采集与查询机制与任务课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"ELK 组件与日志查询笔记","link":"/systems/logging-monitoring/observability/plus/subjects/elk-%E6%97%A5%E5%BF%97%E9%87%87%E9%9B%86","kind":"知识专题","scope":"general","audience":"general"},{"title":"日志采集与查询：基础对象与机制","link":"/systems/logging-monitoring/observability/log-pipeline","kind":"知识专题","scope":"general","audience":"general"},{"title":"SLS 查询与日志分析","link":"/systems/logging-monitoring/observability/plus/ecosystem/sls-query","kind":"命令与查询","scope":"general","audience":"general"}],"prev":{"text":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"日志采集与查询：配置日志采集与批处理","link":"/systems/logging-monitoring/observability/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/logging-monitoring/observability/operations.md","filePath":"systems/logging-monitoring/observability/operations.md"}'),l={name:"systems/logging-monitoring/observability/operations.md"};function s(o,e,n,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="日志采集与查询-发布、排障与恢复练习" tabindex="-1">日志采集与查询：发布、排障与恢复练习 <a class="header-anchor" href="#日志采集与查询-发布、排障与恢复练习" aria-label="Permalink to &quot;日志采集与查询：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">轮转、索引、留存与容量管理 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;轮转、索引、留存与容量管理 {#part-1}&quot;">​</a></h2><p>维护日志多行合并与采集前先保存源文件身份、编码、采集偏移和索引时间窗，恢复后以事件边界、输出确认与查询命中验收。具体配置见<a href="/systems/logging-monitoring/observability/plus/practice/application#source">配套示例</a>。</p><p>核对日期2026-10-17；适用范围：Filebeat 8.19 filestream教学配置；SLS按2026-10-17在线中文文档的查询/索引概念核对，不固定云端后端版本。8.19归档文档不是当前安装建议。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="/systems/logging-monitoring/observability/log-pipeline#part-1-roles">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-1-rotation" tabindex="-1">轮转与队列背压 <a class="header-anchor" href="#part-1-rotation" aria-label="Permalink to &quot;轮转与队列背压 {#part-1-rotation}&quot;">​</a></h3><p>日志轮转背压要联看输入字节增速、输出确认速率、队列容量和磁盘余量。网络不通时有限队列迟早满，应用日志轮转过快会在采集前删除文件；增加重试次数不能创造无限存储。rename保留旧inode有利于读完旧文件，copytruncate存在复制与截断竞态，应根据采集器文件身份机制选择轮转方式。变更input id和路径前保留旧registry，分批核对重复/缺失，不把删除状态当作万能修复。</p><h3 id="part-1-retention" tabindex="-1">索引与留存成本 <a class="header-anchor" href="#part-1-retention" aria-label="Permalink to &quot;索引与留存成本 {#part-1-retention}&quot;">​</a></h3><p>日志索引留存需要将调查窗口、法规保留和成本分开：热索引用于近期筛选，归档用于低频回溯，但归档不一定可直接交互查询。为status建立数值索引才能可靠做范围统计；request_id适合精确追踪，全文索引和高基数字段的成本应评估。修改索引规则可能只影响后续数据，不能宣称历史数据立刻可按新字段搜索。SLS查询先确认索引生效时间，再用同一时间窗比对样本。</p><h3 id="part-1-access" tabindex="-1">查询最小权限与证据导出 <a class="header-anchor" href="#part-1-access" aria-label="Permalink to &quot;查询最小权限与证据导出 {#part-1-access}&quot;">​</a></h3><p>日志导出权限应与采集写入、索引管理分开。排障者只读指定服务和时间窗，导出前删除秘密与个人信息，保留查询表达式、UTC范围、区域和统计口径；不要把完整原始文件贴进工单。采集进程自身日志也可能含发送失败详情，不能误把采集器健康日志当作业务事件成功入库证据。恢复后同时核对积压回落及窗口事件数量，单看服务启动不够。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：积压增加时把重试改为无限就安全了吗？</p><details><summary>参考解答</summary><p>不安全。队列和磁盘有限，源文件可能先轮转删除；应同时调整输入/输出速率、保留窗口与容量预算。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><a href="https://www.elastic.co/guide/en/beats/filebeat/8.19/multiline-examples.html" target="_blank" rel="noopener noreferrer">Filebeat事件合并</a></li><li><a href="https://www.elastic.co/guide/en/beats/filebeat/8.19/filebeat-input-filestream.html" target="_blank" rel="noopener noreferrer">Filebeat filestream</a></li><li><a href="https://www.alibabacloud.com/help/zh/sls/" target="_blank" rel="noopener noreferrer">SLS中文入口</a></li></ul><p>继续阅读<a href="/systems/logging-monitoring/observability/log-pipeline#part-2-multiline">机制</a>、<a href="/systems/logging-monitoring/observability/plus/practice/application#files">完整实践</a>、<a href="#part-1-rotation">运维</a>、<a href="#part-2-empty">诊断</a>与<a href="#part-3-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">日志缺失、重复与格式错误定位 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;日志缺失、重复与格式错误定位 {#part-2}&quot;">​</a></h2><p>本节沿事件边界、输出确认与查询命中定位失败层；先确认源文件身份、编码、采集偏移和索引时间窗，与<a href="/systems/logging-monitoring/observability/plus/practice/application#source">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-empty" tabindex="-1">查询为空的分层诊断 <a class="header-anchor" href="#part-2-empty" aria-label="Permalink to &quot;查询为空的分层诊断 {#part-2-empty}&quot;">​</a></h3><p>日志查询为空时先确认应用确实写了目标文件和事件时间，再检查采集身份、路径、输入状态与输出失败，最后核对索引/分词/时间窗。SLS还应确认Project、Logstore与地域；一个控制台账号登录成功不能证明有目标Logstore查询权限。按request_id在有限窗口选一条已知事件逐层追踪，比同时改十个查询条件更有证据。旧SLS查询页保留完整关键词及SQL写法，可作为特定语法参考。</p><h3 id="part-2-duplicate" tabindex="-1">重复事件与顺序错觉 <a class="header-anchor" href="#part-2-duplicate" aria-label="Permalink to &quot;重复事件与顺序错觉 {#part-2-duplicate}&quot;">​</a></h3><p>日志重复事件不一定是应用重复执行，可能是采集重试、registry重建或多个输入路径同时覆盖同一文件。比较原始event_id、源文件身份、offset和采集器ID，再判别重放。分布式节点的事件时间不能自动形成全局顺序；异步缓冲、时钟偏差和重试都会改变到达顺序，按入库时间排序不能证明因果。调查支付等重要动作应关联业务事务记录，日志只是证据之一。</p><h3 id="part-2-broken" tabindex="-1">乱码与堆栈串接 <a class="header-anchor" href="#part-2-broken" aria-label="Permalink to &quot;乱码与堆栈串接 {#part-2-broken}&quot;">​</a></h3><p>日志格式错误先核对源文件真实编码与换行，再查看首行匹配和续行边界。把所有空格开头都合并会吞掉独立文本记录；把多行放到混合主机流后处理可能将两台机器的异常串在一起。练习：先出现堆栈续行再出现时间头应怎样处理？参考解答：拒绝或隔离孤立行并记录计数，不能悄悄附到下一请求；例子选择整批退出2，读者要明确该取舍。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：同request_id重复出现就说明用户执行两次了吗？</p><details><summary>参考解答</summary><p>不能。采集重试、状态丢失和重叠路径也可能重放，应核对event_id、文件身份和偏移，再查业务事务记录。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">采集重启后日志重复的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;采集重启后日志重复的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将日志多行合并与采集的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/logging-monitoring/observability/plus/practice/application#source">配套示例</a>中的源文件身份、编码、采集偏移和索引时间窗。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>采集器重启后出现重复日志，同时有人建议删除偏移状态重新采集。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>核对源文件身份、轮转方式与偏移持久化目录，确认重启后读取的是原状态还是空状态。</li><li>按事件标识比较源文件、发送结果和索引记录，区分重复读取、重试投递与查询聚合重复。</li><li>检查输出确认、积压与解析失败，注意事件时间和采集时间的差异。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>保存状态与异常样本后修正持久化或轮转配置；需要重放时先界定时间范围、去重方式和目标索引，不用删除状态作为第一步。</p><p>验收：重启和轮转后事件可按预期查询，重复及丢失符合已说明的交付语义；敏感字段在进入共享查询范围前完成保护。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://www.elastic.co/docs/reference/beats/filebeat/how-filebeat-works" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-exercise" tabindex="-1">偏移与脱敏练习 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;偏移与脱敏练习 {#part-3-exercise}&quot;">​</a></h3><p>日志偏移练习：同一事件在文件中由ASCII消息改成三个汉字，下一事件offset会怎样变化？先按UTF-8字节数计算，再对照normalize.py按raw字节累加的实现。参考解答：按实际字节增加，不能按可见字符数或事件序号计；换行CRLF与LF也影响偏移。此结论不代表偏移可跨文件轮转复用，还必须核对文件身份。</p><h3 id="part-3-answer" tabindex="-1">事故窗口复盘 <a class="header-anchor" href="#part-3-answer" aria-label="Permalink to &quot;事故窗口复盘 {#part-3-answer}&quot;">​</a></h3><p>日志事故复盘练习：图表显示错误峰值却查询不到ERROR，是否直接删除索引重建？参考解答：先保全证据，核对指标窗口与日志事件时间、服务标签、脱敏是否移除了message、采集积压及索引字段。例子的Filebeat主动移除自由文本，不能用它证明异常详情存在；若业务需要可调查字段，应设计安全结构化白名单再记录。</p><h3 id="part-3-history" tabindex="-1">历史资料归属 <a class="header-anchor" href="#part-3-history" aria-label="Permalink to &quot;历史资料归属 {#part-3-history}&quot;">​</a></h3><p>原内部业务监控资料已移除；请使用本地示例应用生成指标，再验证采集、标签和查询结果。</p><h3 id="part-3-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-3-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-3-selfcheck}&quot;">​</a></h3><p>练习：原文件CRLF转成LF后，能继续复用旧字节偏移吗？</p><details><summary>参考解答</summary><p>不能。每行字节长度改变，偏移已不对应原始输入；文件身份与内容版本也必须一并核对。</p></details><h3 id="part-3-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-3-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-3-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p><h3 id="part-3-legacy-links" tabindex="-1">保留原文入口 <a class="header-anchor" href="#part-3-legacy-links" aria-label="Permalink to &quot;保留原文入口 {#part-3-legacy-links}&quot;">​</a></h3><ul><li><a href="/systems/logging-monitoring/observability/plus/ecosystem/sls-query">SLS查询与分析原文</a></li><li><a href="/systems/logging-monitoring/observability/plus/subjects/elk-日志采集">ELK职责草稿原文</a></li></ul>',53)])])}const u=a(l,[["render",s]]);export{b as __pageData,u as default};
